# ProtosEQ CRM Day 2 setup (base64 payload version)
# Run from project root: .\day2-setup.ps1

$ErrorActionPreference = 'Stop'

if (-not (Test-Path 'package.json')) {
    Write-Host 'ERROR: run this from your project root.' -ForegroundColor Red
    exit 1
}

$files = @{}
$files['lib/supabase/client.ts'] = 'aW1wb3J0IHsgY3JlYXRlQnJvd3NlckNsaWVudCB9IGZyb20gJ0BzdXBhYmFzZS9zc3InOwoKZXhwb3J0IGZ1bmN0aW9uIGNyZWF0ZUNsaWVudCgpIHsKICByZXR1cm4gY3JlYXRlQnJvd3NlckNsaWVudCgKICAgIHByb2Nlc3MuZW52Lk5FWFRfUFVCTElDX1NVUEFCQVNFX1VSTCEsCiAgICBwcm9jZXNzLmVudi5ORVhUX1BVQkxJQ19TVVBBQkFTRV9BTk9OX0tFWSEKICApOwp9Cg=='
$files['lib/supabase/server.ts'] = ''
$files['lib/supabase/middleware.ts'] = ''
$files['middleware.ts'] = ''
$files['lib/auth/get-user.ts'] = ''
$files['app/(auth)/layout.tsx'] = ''
$files['app/(auth)/login/page.tsx'] = ''
$files['app/auth/callback/route.ts'] = ''
$files['app/(app)/layout.tsx'] = ''
$files['components/app/sidebar.tsx'] = ''
$files['components/app/header.tsx'] = ''
$files['app/(app)/dashboard/page.tsx'] = ''
$files['app/page.tsx'] = ''
$files['app/layout.tsx'] = ''
$files['app/globals.css'] = ''

Write-Host ''
Write-Host '-> Writing files' -ForegroundColor Cyan

foreach ($path in $files.Keys) {
    $content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($files[$path]))
    $dir = Split-Path -Parent $path
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $fullPath = Join-Path -Path (Get-Location) -ChildPath $path
    [System.IO.File]::WriteAllText($fullPath, $content, [System.Text.UTF8Encoding]::new($false))
    Write-Host ('  + ' + $path) -ForegroundColor Green
}

Write-Host ''
Write-Host '====================================' -ForegroundColor Green
Write-Host '  Day 2 setup complete' -ForegroundColor Green
Write-Host '====================================' -ForegroundColor Green
Write-Host ''
Write-Host 'Next steps:' -ForegroundColor Cyan
Write-Host '  1. npm run dev          (test locally at http://localhost:3000)'
Write-Host '  2. git add .'
Write-Host '  3. git commit -m "feat: auth + app shell + protoseq theme"'
Write-Host '  4. git push'
Write-Host ''